class Blog {
    textos: string[]
    titulos : string[]
    autores : string[]
}

function titulosPorAutor(blog: Blog, autor : string) : string[] {
    let resultado : string[] = []
    for (let i : number = 0; i < blog.autores; i++) {
        if (blog.autores[i] == autor) {
            resultado.push(blog.textos[i])
        }
    }
    return autor
}

class IE {
    i : string = ""
    e : string = ""
}

function title(s : string) : string {
    let t : IE = {i : "", e : ""}

    for (let i = 0; i < s.length; i = i + 2) {
        t.i = t.i + s[(i + 4) % s.length]
        t.e = t.e + s[(i + 5) % s.length]
    }

    return t.i + t.e
}
